### FLAC__bitreader_read_raw_uint64
FLAC__bitreader_read_raw_uint64(FLAC__BitReader *br, FLAC__uint64 *val, uint32_t bits)
{
        FLAC__uint32 hi, lo;

        if(bits > 32) {
                if(!FLAC__bitreader_read_raw_uint32(br, &hi, bits-32))
                        return false;
                if(!FLAC__bitreader_read_raw_uint32(br, &lo, 32))
                        return false;
                *val = hi;
                *val <<= 32;
                *val |= lo;
        }
        else {
                if(!FLAC__bitreader_read_raw_uint32(br, &lo, bits))
                        return false;
                *val = lo;
        }
        return true;
}

inline FLAC__bool FLAC__bitreader_read_uint32_little_endian(FLAC__BitReader *br, FLAC__uint32 *val)
{
