        /* this doesn't need to be that fast as currently it is only used for vorbis comments */

        if(!FLAC__bitreader_read_raw_uint32(br, &x32, 8))
                return false;

        if(!FLAC__bitreader_read_raw_uint32(br, &x8, 8))
                return false;
        x32 |= (x8 << 8);

        if(!FLAC__bitreader_read_raw_uint32(br, &x8, 8))
                return false;
        x32 |= (x8 << 16);

        if(!FLAC__bitreader_read_raw_uint32(br, &x8, 8))
                return false;
        x32 |= (x8 << 24);

        *val = x32;
        return true;
}

